class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        def feasible(limit: int) -> bool:
            if limit == 1:
                mismatches = sum(
                    ch != ('0' if i % 2 == 0 else '1')
                    for i, ch in enumerate(s)
                )
                return min(mismatches, n - mismatches) <= numOps

            flips = 0
            run = 1
            for i in range(1, n):
                if s[i] == s[i - 1]:
                    run += 1
                else:
                    flips += run // (limit + 1)
                    run = 1
            flips += run // (limit + 1)
            return flips <= numOps

        lo, hi = 1, n
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

