import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    H, W, N = data[:3]
    bars = []
    p = 3
    for i in range(N):
        r, c, length = data[p:p + 3]
        p += 3
        bars.append((r, c - 1, c - 1 + length, i))

    size = 1
    while size < W:
        size <<= 1
    inf = H + 1
    mn = [inf] * (2 * size)
    lazy = [inf] * (2 * size)

    def push(k):
        v = lazy[k]
        if v != inf:
            for child in (2 * k, 2 * k + 1):
                mn[child] = min(mn[child], v)
                lazy[child] = min(lazy[child], v)
            lazy[k] = inf

    def update(a, b, v, k=1, left=0, right=None):
        if right is None:
            right = size
        if b <= left or right <= a:
            return
        if a <= left and right <= b:
            mn[k] = min(mn[k], v)
            lazy[k] = min(lazy[k], v)
            return
        push(k)
        mid = (left + right) // 2
        update(a, b, v, 2 * k, left, mid)
        update(a, b, v, 2 * k + 1, mid, right)
        mn[k] = min(mn[2 * k], mn[2 * k + 1])

    def query(a, b, k=1, left=0, right=None):
        if right is None:
            right = size
        if b <= left or right <= a:
            return inf
        if a <= left and right <= b:
            return mn[k]
        push(k)
        mid = (left + right) // 2
        return min(query(a, b, 2 * k, left, mid),
                   query(a, b, 2 * k + 1, mid, right))

    answer = [0] * N
    for row, a, b, i in sorted(bars, key=lambda x: -x[0]):
        nearest_below = query(a, b)
        final_row = min(H, nearest_below - 1)
        answer[i] = final_row
        update(a, b, final_row)

    sys.stdout.write("\n".join(map(str, answer)))

if __name__ == "__main__":
    main()

