from typing import List

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def feasible(target: int) -> bool:
            if target == 0:
                return True
            moves = 1  # first move enters index 0
            if moves > m:
                return False
            count = 1  # visits at index 0

            for i in range(n - 1):
                required = (target + points[i] - 1) // points[i]
                extra = max(0, required - count)
                moves += 2 * extra
                if moves > m:
                    return False

                # Excursions from i visit i+1 extra times. On the final
                # edge, we may finish here without advancing again.
                if i == n - 2:
                    last_required = (target + points[i + 1] - 1) // points[i + 1]
                    if extra >= last_required:
                        return True
                moves += 1
                if moves > m:
                    return False
                count = extra + 1

            required = (target + points[-1] - 1) // points[-1]
            extra = max(0, required - count)
            return moves + 2 * extra <= m

        lo, hi = 0, (m * max(points)) // 2 + max(points)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

