from typing import List
from math import gcd

class Solution:
    def subsequencePairCount(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        dp = [[0] * 201 for _ in range(201)]
        dp[0][0] = 1

        for x in nums:
            ndp = [[0] * 201 for _ in range(201)]
            for a in range(201):
                for b, ways in enumerate(dp[a]):
                    if ways:
                        ndp[a][b] = (ndp[a][b] + ways) % MOD
                        ga = gcd(a, x)
                        ndp[ga][b] = (ndp[ga][b] + ways) % MOD
                        gb = gcd(b, x)
                        ndp[a][gb] = (ndp[a][gb] + ways) % MOD
            dp = ndp

        return sum(dp[g][g] for g in range(1, 201)) % MOD

