from typing import List

class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if n - 1 < k:
            return [0] * n

        # Trie counts: cnt[v] is the number of words having the prefix at v.
        children = [{}]
        cnt = [0]
        depth = [0]
        for word in words:
            node = 0
            for ch in word:
                nxt = children[node].get(ch)
                if nxt is None:
                    nxt = len(children)
                    children[node][ch] = nxt
                    children.append({})
                    cnt.append(0)
                    depth.append(depth[node] + 1)
                node = nxt
                cnt[node] += 1

        max_depth = max(depth)
        qualifying_at_depth = [0] * (max_depth + 1)
        for node in range(1, len(cnt)):
            if cnt[node] >= k:
                qualifying_at_depth[depth[node]] += 1

        # Depths with at least two qualifying prefixes cannot be lost by one removal.
        answer_base = max(
            (d for d, total in enumerate(qualifying_at_depth) if total >= 2),
            default=0,
        )

        # A singleton qualifying prefix is lost only when its count is exactly k
        # and the removed word has that prefix.
        critical = {
            depth[node]: node
            for node in range(1, len(cnt))
            if cnt[node] == k and qualifying_at_depth[depth[node]] == 1
        }
        candidates = sorted(critical, reverse=True)

        # Singleton prefixes with count > k are unaffected by any removal.
        for d, total in enumerate(qualifying_at_depth):
            if total == 1 and d not in critical:
                answer_base = max(answer_base, d)

        result = []
        for word in words:
            node = 0
            lost_depths = set()
            for d, ch in enumerate(word, 1):
                node = children[node][ch]
                if critical.get(d) == node:
                    lost_depths.add(d)

            answer = answer_base
            for d in candidates:
                if d not in lost_depths:
                    answer = max(answer, d)
                    break
            result.append(answer)

        return result

