from typing import List
class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n=len(words)
        if n-1<k: return [0]*n
        children=[{}]
        cnt=[0]
        depth=[0]
        for w in words:
            v=0
            for ch in w:
                u=children[v].get(ch)
                if u is None:
                    u=len(children); children[v][ch]=u
                    children.append({}); cnt.append(0); depth.append(depth[v]+1)
                v=u; cnt[v]+=1
        q=[0]*(max(depth)+1)
        for v in range(1,len(cnt)):
            if cnt[v]>=k: q[depth[v]]+=1
        base=max((d for d,x in enumerate(q) if x>=2),default=0)
        critical={depth[v]:v for v in range(1,len(cnt)) if cnt[v]==k and q[depth[v]]==1}
        cand=sorted((d for d,x in enumerate(q) if x==1 and d in critical),reverse=True)
        # singleton noncritical nodes always remain; but q==1 node with count > k is safe
        safe=max((d for d in range(1,len(q)) if q[d]==1 and d not in critical),default=0)
        base=max(base,safe)
        ans=[]
        for w in words:
            v=0; invalid=set()
            for d,ch in enumerate(w,1):
                v=children[v][ch]
                if critical.get(d)==v: invalid.add(d)
            a=base
            for d in cand:
                if d not in invalid:
                    a=max(a,d); break
            ans.append(a)
        return ans

