class Solution:
    def longestSpecialPath(self, edges: List[List[int]], nums: List[int]) -> List[int]:
        n = len(nums)
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))
        last = {}
        best = -1
        min_nodes = n + 1
        # (node, parent, distance, left, exiting, value, old)
        stack = [(0, -1, 0, 0, False, 0, -1)]
        while stack:
            node, parent, dist, left, exiting, value, old = stack.pop()
            if exiting:
                if old == -1:
                    del last[value]
                else:
                    last[value] = old
                continue
            value = nums[node]
            old = last.get(value, -1)
            new_left = max(left, old + 1)
            last[value] = dist  # depth index? dist is weighted, incorrect
            # placeholder
            stack.append((node, parent, dist, left, True, value, old))
            for child, weight in graph[node]:
                if child != parent:
