import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]

    # factorials for binomial coefficients
    fact = [1] * (2 * n + 1)
    for i in range(1, 2 * n + 1):
        fact[i] = fact[i - 1] * i % MOD
    invfact = [1] * (2 * n + 1)
    invfact[2 * n] = pow(fact[2 * n], MOD - 2, MOD)
    for i in range(2 * n, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    def comb(x, y):
        if y < 0 or y > x:
            return 0
        return fact[x] * invfact[y] % MOD * invfact[x - y] % MOD

    ans = 0
    slots = 1
    still_equal = True

    for i, value in enumerate(a):
        if not still_equal:
            break

        remaining = n - i - 1
        # Try a smaller value at this position, then count all completions.
        lo = slots - 1
        hi = min(slots - 1 + value - 1, remaining)
        for q in range(lo, hi + 1):
            if q == 0:
                if remaining == 0:
                    ans += 1
                continue
            if remaining:
                ans += q * comb(2 * remaining - q - 1, remaining - q)
                ans %= MOD

        slots = slots - 1 + value
        if slots <= 0:
            still_equal = False
        elif slots > remaining:
            still_equal = False

    # Include A itself if it is Polish.
    if still_equal and slots == 0:
        ans += 1

    print(ans % MOD)

if __name__ == "__main__":
    main()

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        length = n + m - 1
        word = ['a'] * length
        fixed = [False] * length

        # Apply all substring requirements imposed by T positions.
        for i, flag in enumerate(str1):
            if flag == 'T':
                for j, ch in enumerate(str2):
                    pos = i + j
                    if fixed[pos] and word[pos] != ch:
                        return ""
                    word[pos] = ch
                    fixed[pos] = True

        # For each F window that currently equals str2, change its
        # rightmost position not constrained by any T window.
        for i, flag in enumerate(str1):
            if flag == 'F' and word[i:i + m] == list(str2):
                pos = i + m - 1
                while pos >= i and fixed[pos]:
                    pos -= 1
                if pos < i:
                    return ""
                target = str2[pos - i]
                word[pos] = 'a' if target != 'a' else 'b'

        # Verify that changes made for F windows did not violate any
        # other requirement.
        for i, flag in enumerate(str1):
            matches = True
            for j, ch in enumerate(str2):
                if word[i + j] != ch:
                    matches = False
                    break
            if (flag == 'T') != matches:
                return ""

        return ''.join(word)

