from typing import List
from bisect import bisect_right

class Solution:
    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        a = sorted((l, r, w, i) for i, (l, r, w) in enumerate(intervals))
        n = len(a)
        starts = [item[0] for item in a]
        nxt = [bisect_right(starts, item[1]) for item in a]

        # dp[i][k] is (maximum score, lexicographically smallest index tuple)
        # obtainable from sorted position i onward using at most k intervals.
        dp = [[(0, ()) for _ in range(5)] for _ in range(n + 1)]
        for i in range(n - 1, -1, -1):
            _, _, weight, index = a[i]
            for k in range(1, 5):
                skip = dp[i + 1][k]
                following_score, following_indices = dp[nxt[i]][k - 1]
                take = (weight + following_score,
                        tuple(sorted((index,) + following_indices)))
                if take[0] > skip[0] or (take[0] == skip[0] and take[1] < skip[1]):
                    dp[i][k] = take
                else:
                    dp[i][k] = skip
        return list(dp[0][4][1])

