import bisect


def make_histogram(values, limit):
    values.sort()
    n = len(values)
    prefix = [0] * (n + 1)
    for i, value in enumerate(values):
        prefix[i + 1] = prefix[i] + value

    def cost(t):
        k = bisect.bisect_right(values, t)
        return t * k - prefix[k] + (prefix[n] - prefix[k]) - t * (n - k)

    median = values[n // 2]
    if cost(median) > limit:
        return [0] * (limit + 1)

    # On the left of a median, cost is nonincreasing.
    lo, hi = median - limit, median
    while lo < hi:
        mid = (lo + hi) // 2
        if cost(mid) <= limit:
            hi = mid
        else:
            lo = mid + 1
    left = lo

    # On the right, cost is nondecreasing.
    lo, hi = median, median + limit
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if cost(mid) <= limit:
            lo = mid
        else:
            hi = mid - 1
    right = lo

    counts = [0] * (limit + 1)
    t = left
    current_cost = cost(t)
    k = bisect.bisect_right(values, t)
    while t <= right:
        counts[current_cost] += 1
        # cost(t+1) - cost(t) = 2 * #{xi <= t} - n
        current_cost += 2 * k - n
        t += 1
        while k < n and values[k] <= t:
            k += 1
    return counts


