class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        if n < 3:
            return ""

        # pref[c][i] is the cost of changing caption[:i] to character c.
        chars = [ord(ch) - 97 for ch in caption]
        pref = [[0] * (n + 1) for _ in range(26)]
        for c in range(26):
            row = pref[c]
            for i, x in enumerate(chars):
                row[i + 1] = row[i] + abs(x - c)

        inf = 10**18
        dp = [inf] * (n + 1)
        choice = [None] * n
        dp[n] = 0

        # For each letter, maintain the best endpoint j >= i+3 for
        # dp[j] + cost(caption[j:], c) - cost(caption[i:], c).
        best_val = [inf] * 26
        best_end = [None] * 26

        for i in range(n - 3, -1, -1):
            j = i + 3
            if dp[j] < inf:
                for c in range(26):
                    value = dp[j] + pref[c][n] - pref[c][j]
                    if value < best_val[c]:
                        best_val[c] = value
                        best_end[c] = j

            best_cost = inf
            best_c = -1
            best_j = -1
            for c in range(26):
                if best_end[c] is None:
                    continue
                cost = best_val[c] - (pref[c][n] - pref[c][i])
                if cost < best_cost or (cost == best_cost and c < best_c):
                    best_cost, best_c, best_j = cost, c, best_end[c]

            if best_c >= 0:
                dp[i] = best_cost
                choice[i] = (best_c, best_j)

        if dp[0] >= inf:
            return ""

        result = []
        i = 0
        while i < n:
            c, j = choice[i]
            result.append(chr(97 + c) * (j - i))
            i = j
        return "".join(result)

