MOD = 998244353
ROOT = 3

def ntt(a, invert):
    n = len(a)
    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]
    length = 2
    while length <= n:
        wlen = pow(ROOT, (MOD - 1) // length, MOD)
        if invert:
            wlen = pow(wlen, MOD - 2, MOD)
        half = length >> 1
        for start in range(0, n, length):
            w = 1
            end = start + half
            for k in range(start, end):
                u = a[k]
                v = a[k + half] * w % MOD
                x = u + v
                if x >= MOD:
                    x -= MOD
                y = u - v
                if y < 0:
                    y += MOD
                a[k] = x
                a[k + half] = y
                w = w * wlen % MOD
        length <<= 1
    if invert:
        invn = pow(n, MOD - 2, MOD)
        for i in range(n):
            a[i] = a[i] * invn % MOD

