from typing import List

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        off = sum(nums)
        target = k + off
        if target < 0 or target > 2 * off:
            return -1

        # dp[parity][product] is a bitset of attainable alternating sums,
        # with parity being the length modulo 2. Products above limit are
        # grouped separately: they only become relevant if a later zero is picked.
        dp = [[0] * (limit + 1) for _ in range(2)]
        overflow = [0, 0]

        for x in nums:
            nd = [row.copy() for row in dp]  # skip this element
            no = overflow.copy()

            # Start a new, nonempty subsequence with this element.
            singleton = 1 << (off + x)
            nd[1][x] |= singleton

            for parity in range(2):
                dest = 1 - parity
                delta = x if parity == 0 else -x
                for prod, bits in enumerate(dp[parity]):
                    if not bits:
                        continue
                    moved = bits << delta if delta >= 0 else bits >> (-delta)
                    newprod = prod * x
                    if newprod <= limit:
                        nd[dest][newprod] |= moved
                    else:
                        no[dest] |= moved

                bits = overflow[parity]
                if bits:
                    moved = bits << delta if delta >= 0 else bits >> (-delta)
                    if x == 0:
                        nd[dest][0] |= moved
                    else:
                        no[dest] |= moved
            dp, overflow = nd, no

        bit = 1 << target
        for prod in range(limit, -1, -1):
            if (dp[0][prod] | dp[1][prod]) & bit:
                return prod
        return -1

