class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        parent = list(range(n))
        size = [1] * n
        components = n

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            nonlocal components
            a = find(a)
            b = find(b)
            if a != b:
                if size[a] < size[b]:
                    a, b = b, a
                parent[b] = a
                size[a] += size[b]
                components -= 1

        # Numbers sharing a multiple <= threshold have LCM <= threshold.
        # For each multiple, retain one encountered number dividing it.
        first = [-1] * (threshold + 1)
        for i, x in enumerate(nums):
            if x > threshold:
                continue
            for multiple in range(x, threshold + 1, x):
                j = first[multiple]
                if j == -1:
                    first[multiple] = i
                else:
                    union(i, j)

        return components

