from typing import List

class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        def prefix(x: int) -> int:
            total = 0
            start = 1
            steps = 1
            while start <= x:
                end = min(x, start * 4 - 1)
                total += (end - start + 1) * steps
                start *= 4
                steps += 1
            return total

        answer = 0
        for left, right in queries:
            work = prefix(right) - prefix(left - 1)
            answer += (work + 1) // 2
        return answer

