from typing import List
from bisect import bisect_left

class Solution:
    def maxPathLength(self, coordinates: List[List[int]], k: int) -> int:
        xk, yk = coordinates[k]

        # Longest chain ending at the selected point.
        left = [(x, y) for x, y in coordinates if x < xk and y < yk]
        left.sort(key=lambda p: (p[0], -p[1]))
        tails = []
        for _, y in left:
            i = bisect_left(tails, y)
            if i == len(tails):
                tails.append(y)
            else:
                tails[i] = y
        before = len(tails)

        # Reverse the order of chains after the selected point and find
        # their longest increasing subsequence in the negated y values.
        right = [(x, y) for x, y in coordinates if x > xk and y > yk]
        right.sort(key=lambda p: (-p[0], p[1]))
        tails = []
        for _, y in right:
            value = -y
            i = bisect_left(tails, value)
            if i == len(tails):
                tails.append(value)
            else:
                tails[i] = value

        return before + 1 + len(tails)

