from typing import List

class Solution:
    def minDifference(self, nums: List[int]) -> int:
        n = len(nums)
        base = max(
            (abs(nums[i] - nums[i - 1])
             for i in range(1, n)
             if nums[i] != -1 and nums[i - 1] != -1),
            default=0,
        )

        # A run of one missing value between two fixed values must use a
        # single replacement close to both. Other run endpoints can be
        # assigned independently to either of the two chosen values.
        constraints = []
        i = 0
        while i < n:
            if nums[i] != -1:
                i += 1
                continue
            j = i
            while j < n and nums[j] == -1:
                j += 1

            left = nums[i - 1] if i > 0 else None
            right = nums[j] if j < n else None
            if j - i == 1 and left is not None and right is not None:
                constraints.append((left, right))
            else:
                if left is not None:
                    constraints.append((left,))
                if right is not None:
                    constraints.append((right,))
            i = j

        def feasible(d: int) -> bool:
            intervals = []
            for c in constraints:
                if len(c) == 2:
                    a, b = c
                    low = max(1, a - d, b - d)
                    high = min(a + d, b + d)
                else:
                    a = c[0]
                    low = max(1, a - d)
                    high = a + d
                if low > high:
                    return False
                intervals.append((low, high))

            # Greedy minimum interval stabbing; at most two centers are
            # available, and each center must lie in every interval it serves.
            intervals.sort(key=lambda interval: interval[1])
            centers = []
            for low, high in intervals:
                if not centers or not (low <= centers[-1] <= high):
                    centers.append(high)
            return len(centers) <= 2

        low, high = base, 10**9
        while low < high:
            mid = (low + high) // 2
            if feasible(mid):
                high = mid
            else:
                low = mid + 1
        return low

