        if remaining == 0:
            return 1
        count = 0
        for u in adj[v]:
            bit = 1 << u
            if not visited & bit:
                count += dfs(u, remaining - 1, visited | bit)
        return count

    answer = sum(dfs(start, K, 1 << start) for start in range(n))
    print(answer)

