class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)

        # Diagonals on and below the main diagonal: non-increasing.
        for r0 in range(n):
            positions = [(r0 + k, k) for k in range(n - r0)]
            values = sorted((grid[r][c] for r, c in positions), reverse=True)
            for (r, c), value in zip(positions, values):
                grid[r][c] = value

        # Diagonals strictly above the main diagonal: non-decreasing.
        for c0 in range(1, n):
            positions = [(k, c0 + k) for k in range(n - c0)]
            values = sorted(grid[r][c] for r, c in positions)
