from typing import List

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        events.sort(key=lambda e: int(e[1]))
        mentions = [0] * numberOfUsers
        online_until = [0] * numberOfUsers  # 0 means online; otherwise time of automatic return
        i = 0
        while i < len(events):
            t = int(events[i][1])
            j = i
            while j < len(events) and int(events[j][1]) == t:
                j += 1

            for u in range(numberOfUsers):
                if online_until[u] and online_until[u] <= t:
                    online_until[u] = 0

            # Apply every offline transition before processing messages at this timestamp.
            for k in range(i, j):
                typ, _, value = events[k]
                if typ == "OFFLINE":
                    online_until[int(value)] = t + 60

            for k in range(i, j):
                typ, _, text = events[k]
                if typ != "MESSAGE":
                    continue
                if text == "ALL":
                    for u in range(numberOfUsers):
                        mentions[u] += 1
                elif text == "HERE":
                    for u in range(numberOfUsers):
                        if online_until[u] == 0:
                            mentions[u] += 1
                else:
                    for token in text.split():
                        mentions[int(token[2:])] += 1
            i = j
        return mentions

