import heapq

class Solution:
    def resultsArray(self, queries: List[List[int]], k: int) -> List[int]:
        heap = []  # negative distances of the k smallest seen
        result = []
        for x, y in queries:
            d = abs(x) + abs(y)
            heapq.heappush(heap, -d)
            if len(heap) > k:
                heapq.heappop(heap)
            result.append(-heap[0] if len(heap) == k else -1)
        return result

