from typing import List

class Solution:
    def maxPossibleScore(self, start: List[int], d: int) -> int:
        intervals = sorted(start)
        n = len(intervals)

        def feasible(gap: int) -> bool:
            chosen = intervals[0]
            for left in intervals[1:]:
                chosen = max(left, chosen + gap)
                if chosen > left + d:
                    return False
            return True

        lo, hi = 0, (intervals[-1] + d - intervals[0]) // (n - 1) + 1
        while lo + 1 < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid
        return lo

