        pref=[]
        s=0
        for x in skill:
            s+=x
            pref.append(s)
        starts=0
        for j in range(1,len(mana)):
            prev=mana[j-1]; cur=mana[j]
            gap=max(pref[i]*prev - (pref[i]-skill[i])*cur for i in range(len(skill)))
